[versions]
commonstext       = "1.13.0"
javalin           = "7.1.0"
resilience4j      = "2.2.0"
jackson           = "2.17.0"
okhttp            = "4.12.0"
jdbi              = "3.45.4"
h2                = "2.2.224"
postgresql        = "42.7.3"
